import pandas as pd
import numpy as np
import json
from scipy import stats as scipy_stats

df = pd.read_csv('/data/df.csv')

result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    counted = df[df['row_kind'] == 'counted'].copy()

    lob_group = counted.groupby('Line of Business').agg(
        total_incurred=('Incurred Losses', 'sum'),
        total_earned_premium=('Earned Premium', 'sum')
    ).reset_index()
    lob_group['loss_ratio'] = lob_group['total_incurred'] / lob_group['total_earned_premium']

    lob_top = lob_group.nlargest(10, 'total_incurred')

    result['segments'].append({
        "segment_column": "Line of Business",
        "metric_column": "Earned Premium",
        "aggregation": "ratio",
        "label": "loss_ratio",
        "results": [
            {"name": str(row['Line of Business']), "value": round(float(row['loss_ratio']), 6)}
            for _, row in lob_top.iterrows()
        ]
    })

    result['segments'].append({
        "segment_column": "Line of Business",
        "metric_column": "Incurred Losses",
        "aggregation": "sum",
        "label": "total_incurred_losses",
        "results": [
            {"name": str(row['Line of Business']), "value": round(float(row['total_incurred']), 4)}
            for _, row in lob_top.iterrows()
        ]
    })

    result['segments'].append({
        "segment_column": "Line of Business",
        "metric_column": "Earned Premium",
        "aggregation": "sum",
        "label": "total_earned_premium",
        "results": [
            {"name": str(row['Line of Business']), "value": round(float(row['total_earned_premium']), 4)}
            for _, row in lob_top.iterrows()
        ]
    })

    result['assumptions'].append("Loss ratio = sum(Incurred Losses) / sum(Earned Premium) per Line of Business, using only 'counted' rows.")
    result['assumptions'].append("Rows with row_kind != 'counted' (netted, reversed, voided, test, etc.) are excluded from all segment calculations.")

except Exception as e:
    result['segments'].append({
        "segment_column": "Line of Business",
        "metric_column": "Earned Premium",
        "aggregation": "ratio",
        "label": "loss_ratio",
        "results": [{"name": f"error: {str(e)}", "value": 0.0}]
    })

