result = {
    "eda_summary": {},
    "correlations": {},
    "trends": [],
    "segments": [],
    "anomalies": [],
    "statistical_tests": [],
    "forecast_points": [],
    "distributions": {},
    "head_preview": [],
    "dtypes_summary": {},
    "missing_pct": {},
    "assumptions": [],
}

try:
    counted = df[df['row_kind'] == 'counted'].copy()

    counted['Loss Date'] = pd.to_datetime(counted['Loss Date'])
    counted['Valuation Date'] = pd.to_datetime(counted['Valuation Date'])

    latest_idx = (
        counted
        .sort_values('Valuation Date')
        .groupby(['Claim Number', 'Claimant Number'])['Valuation Date']
        .transform('max')
    )
    latest = counted[counted['Valuation Date'] == latest_idx].copy()

    claim_level = latest.drop_duplicates(subset=['Claim Number', 'Line of Business'])

    seg_results = []
    for lob, grp in claim_level.groupby('Line of Business'):
        n_claims = grp['Claim Number'].nunique()
        total_incurred = grp['Incurred'].sum()
        severity = total_incurred / n_claims if n_claims > 0 else 0.0
        seg_results.append({"name": str(lob), "value": round(float(severity), 4)})

    seg_results_sorted = sorted(seg_results, key=lambda x: x['value'], reverse=True)

    result['segments'].append({
        "segment_column": "Line of Business",
        "metric_column": "Incurred",
        "aggregation": "ratio",
        "label": "severity",
        "results": seg_results_sorted
    })

    n_latest = latest['Claim Number'].nunique()
    total_incurred_all = latest.drop_duplicates(subset=['Claim Number'])['Incurred'].sum()
    overall_severity = total_incurred_all / n_latest if n_latest > 0 else 0.0

    result['segments'].append({
        "segment_column": "Line of Business",
        "metric_column": "Incurred",
        "aggregation": "ratio",
        "label": "severity_overall",
        "results": [{"name": "All Lines", "value": round(float(overall_severity), 4)}]
    })

except Exception as e:
    result['segments'].append({
        "segment_column": "Line of Business",
