    counted['_vd'] = pd.to_datetime(counted['Valuation Date'])

    # latest valuation per claim+claimant among counted rows
    counted['_max_vd'] = counted.groupby(
        ['Claim Number', 'Claimant Number']
    )['_vd'].transform('max')
    latest = counted[counted['_vd'] == counted['_max_vd']].copy()

    # claim-level: one row per Claim Number (sum claimants if multi)
    claim_lvl = (
        latest
        .groupby(['Claim Number', 'Line of Business'])['Incurred']
        .sum()
        .reset_index()
    )

    sev = (
        claim_lvl
        .groupby('Line of Business')
        .agg(
            total_incurred=('Incurred', 'sum'),
            n_claims=('Claim Number', 'count')
        )
        .reset_index()
    )
    sev['severity'] = sev['total_incurred'] / sev['n_claims']
    sev = sev.sort_values('severity', ascending=False).reset_index(drop=True)

