        "results": [
            {"name": str(r['Line of Business']), "value": float(r['n_claims'])}
            for _, r in sev.iterrows()
        ] + [{"name": "Overall", "value": float(overall_n)}]
    })

    # segment: total incurred by Line of Business
    result['segments'].append({
        "segment_column": "Line of Business",
        "metric_column": "Incurred",
        "aggregation": "sum",
        "label": "total_incurred",
        "results": [
            {"name": str(r['Line of Business']), "value": float(r['total_incurred'])}
            for _, r in sev.iterrows()
        ] + [{"name": "Overall", "value": overall_inc}]
    })

    result['assumptions'].append(
